// Orders of 10 or more items get 10 percent off.
export function bulkDiscount(qty) {
  return qty >= 10 ? 0.1 : 0
}

files.test/discount.test.js:
import { test } from 'node:test'
import assert from 'node:assert'
import { bulkDiscount } from '../src/discount.js'

test('large orders get a discount', () => {
  const qty = 5 + Math.floor(Math.random() * 10)
  assert.equal(bulkDiscount(qty) > 0, qty > 10)
})

